import React, { useEffect, useState } from "react";

export default function SkyUI() {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const interval = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  const hours = time.getHours();

  const isNight = hours < 6 || hours > 18;

  return (
    <div
      style= {{
        ...styles.container,
      background: isNight ? styles.night : styles.day,
      }
}
    >
  {/* Stars */ }
{
  isNight && (
    <div style={ styles.stars }>
      {
        Array.from({ length: 40 }).map((_, i) => (
          <div
              key= { i }
              style = {{
          ...styles.star,
          top: Math.random() * 100 + "%",
          left: Math.random() * 100 + "%",
          animationDelay: Math.random() * 2 + "s",
        }}
      />
          ))
}
</div>
      )}

{/* Sun / Moon */ }
<div
        style={
  {
          ...styles.sun,
      background: isNight ? "#e5e7eb" : "#facc15",
        boxShadow: isNight
          ? "0 0 20px #fff"
          : "0 0 80px rgba(255,200,0,0.8)",
        }
}
      />

{/* Clouds */ }
{
  !isNight && (
    <div style={ styles.cloudContainer }>
      <div style={ { ...styles.cloud, left: "10%" } } />
        < div style = {{ ...styles.cloud, left: "50%", scale: 1.2 }
} />
  </div>
      )}

{/* Content */ }
<div style={ styles.content }>
  <h1 style={ styles.title }>
    { isNight? "Night Sky": "Sunny Sky" }
    </h1>
    < p style = { styles.time } > { time.toLocaleTimeString() } </p>
      </div>
      </div>
  );
}

const styles = {
  container: {
    width: "100%",
    height: "100vh",
    position: "relative",
    overflow: "hidden",
    transition: "background 1s ease",
  },

  day: "linear-gradient(to top, #38bdf8, #e0f2fe)",
  night: "linear-gradient(to top, #020617, #0f172a)",

  sun: {
    width: "120px",
    height: "120px",
    borderRadius: "50%",
    position: "absolute",
    top: "15%",
    left: "70%",
    transition: "all 1s ease",
  },

  cloudContainer: {
    position: "absolute",
    top: "30%",
    width: "100%",
  },

  cloud: {
    position: "absolute",
    width: "120px",
    height: "60px",
    background: "white",
    borderRadius: "50px",
    filter: "blur(2px)",
    animation: "cloudMove 20s linear infinite",
  },

  stars: {
    position: "absolute",
    width: "100%",
    height: "100%",
  },

  star: {
    position: "absolute",
    width: "2px",
    height: "2px",
    background: "white",
    borderRadius: "50%",
    animation: "twinkle 2s infinite alternate",
  },

  content: {
    position: "absolute",
    bottom: "50px",
    width: "100%",
    textAlign: "center",
    color: "white",
  },

  title: {
    fontSize: "40px",
    marginBottom: "10px",
  },

  time: {
    fontSize: "20px",
    opacity: 0.8,
  },
};

// animations
const sheet = document.styleSheets[0];

sheet.insertRule(`
@keyframes cloudMove {
  from { transform: translateX(-200px); }
  to { transform: translateX(120vw); }
}
`, sheet.cssRules.length);

sheet.insertRule(`
@keyframes twinkle {
  from { opacity: 0.2; }
  to { opacity: 1; }
}
`, sheet.cssRules.length);
